package com.joshualee0902.myapplication;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeMap;

/**
 * Parity: the Java engine must reproduce the Python reference on the shared fixtures in
 * tests/fixtures/parity/ (generated by tests/parity_cases.py; synthetic data).
 */
public class ParityTest {
    private static final double TOL = 1e-9;

    private static File fixtureDir() {
        // Gradle runs unit tests with the module (app/) as working directory.
        for (String p : new String[]{"../tests/fixtures/parity", "tests/fixtures/parity"}) {
            File f = new File(p);
            if (f.isDirectory()) return f;
        }
        throw new IllegalStateException("parity fixtures not found from " + new File(".").getAbsolutePath());
    }

    private static double num(JSONObject o, String key) {
        return o.isNull(key) ? Double.NaN : o.getDouble(key);
    }

    @Test
    public void javaEngineMatchesPythonReferenceOnEveryFixture() throws Exception {
        File[] files = fixtureDir().listFiles((d, n) -> n.endsWith(".json"));
        assertTrue("no parity fixtures found", files != null && files.length >= 5);
        Arrays.sort(files);
        for (File f : files) {
            JSONObject c = new JSONObject(new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8));
            runCase(c);
        }
    }

    private void runCase(JSONObject c) throws Exception {
        String name = c.getString("name");
        ModelParams params = ModelParams.parse(c.getJSONObject("params"));

        TreeMap<Integer, double[]> ratings = new TreeMap<>();
        JSONArray snap = c.getJSONArray("snapshot");
        for (int i = 0; i < snap.length(); i++) {
            JSONObject r = snap.getJSONObject(i);
            ratings.put(r.getInt("team"), new double[]{num(r, "auto_opr"), num(r, "teleop_opr"), num(r, "endgame_opr")});
        }
        List<MatchRecord> scouting = new ArrayList<>();
        JSONArray sc = c.getJSONArray("scouting");
        for (int i = 0; i < sc.length(); i++) {
            JSONObject r = sc.getJSONObject(i);
            MatchRecord m = new MatchRecord();
            m.teamNumber = r.getInt("team_num");
            m.defenseRating = r.getInt("defense_rating");
            m.climbed = r.getInt("climbed") != 0;
            m.bricked = r.getInt("bricked") != 0;
            m.fouls = r.getInt("fouls");
            scouting.add(m);
        }

        FeatureBuilder.Table table = FeatureBuilder.build(params, ratings, scouting);

        JSONArray ef = c.getJSONArray("expected_features");
        assertEquals(name + ": team count", ef.length(), table.teams.length);
        for (int i = 0; i < ef.length(); i++) {
            JSONObject row = ef.getJSONObject(i);
            assertEquals(name + ": team order", row.getInt("team"), table.teams[i]);
            assertArrayEquals(name + ": z-features of team " + table.teams[i],
                    ModelParams.doubles(row.getJSONArray("z")), table.z[i], TOL);
        }

        List<Integer> pool = new ArrayList<>();
        JSONArray pj = c.getJSONArray("pool");
        for (int i = 0; i < pj.length(); i++) pool.add(pj.getInt(i));
        PartnerMatcher.Draft draft = new PartnerMatcher.Draft(table, params, c.getInt("captain"), pool);

        JSONArray expected = c.getJSONArray("expected_results");
        JSONArray actions = c.getJSONArray("actions");
        int r = 0;
        for (int a = 0; a < actions.length(); a++) {
            JSONObject act = actions.getJSONObject(a);
            switch (act.getString("op")) {
                case "pick": draft.pick(act.getInt("team")); break;
                case "decline": draft.decline(act.getInt("team")); break;
                case "recommend": {
                    JSONObject exp = expected.getJSONObject(r++);
                    List<PartnerMatcher.Ranked> got = draft.recommend(act.optInt("n", 0));
                    assertArrayEquals(name + ": target", ModelParams.doubles(exp.getJSONArray("target")), draft.target(), TOL);
                    JSONArray ranking = exp.getJSONArray("ranking");
                    assertEquals(name + ": ranking length", ranking.length(), got.size());
                    for (int i = 0; i < ranking.length(); i++) {
                        JSONObject e = ranking.getJSONObject(i);
                        assertEquals(name + ": rank " + (i + 1) + " team", e.getInt("team"), got.get(i).team);
                        assertEquals(name + ": distance of " + e.getInt("team"), e.getDouble("distance"), got.get(i).distance, TOL);
                        assertArrayEquals(name + ": contributions of " + e.getInt("team"),
                                ModelParams.doubles(e.getJSONArray("contrib")), got.get(i).contributions, TOL);
                    }
                    break;
                }
                default: throw new IllegalStateException(act.getString("op"));
            }
        }
        assertEquals(name + ": all expected results consumed", expected.length(), r);
    }
}
